import numpy as np, re
from scipy.io import wavfile
ns={}; exec(open('names.py',encoding='utf8').read().split("h='''")[0],ns)
sr=44100; pulse=0.28; bar=6*pulse
def syl(l):
    return max(1,len(re.findall(r'[aeiou]+',l.lower())))
def pluck(f,d=0.5):
    t=np.arange(int(sr*d))/sr
    return np.sin(2*np.pi*f*t)*np.exp(-t*9)+0.3*np.sin(2*np.pi*2*f*t)*np.exp(-t*14)
freq={'#c41e3a':147,'#244896':196,'#d9a01e':294}
out=np.zeros(int(sr*(bar*44+2)))
b=0
for name,col,ar,lat in ns['R']:
    for l in lat.split('|'):
        n=min(syl(l),6); pos=sorted(set(int(round(i*6/n)) for i in range(n)))
        for k,p in enumerate(pos):
            s=int(sr*(b*bar+p*pulse)); w=pluck(freq[col]*(1.5 if k==len(pos)-1 and len(pos)>1 else 1))*0.5
            out[s:s+len(w)]+=w
        s=int(sr*b*bar); w=pluck(freq[col]/2,0.3)*0.4; out[s:s+len(w)]+=w
        b+=1
out/=abs(out).max()*1.05
wavfile.write('names-beaten.wav',sr,(out*32767).astype(np.int16))
EOF
